CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TYPE content_state AS ENUM ('DRAFT','PENDING','CHANGES_REQUESTED','APPROVED','REJECTED','ARCHIVED');
CREATE TYPE visibility_level AS ENUM ('COMPANY','CROSS_DEPARTMENT','DEPARTMENT','RESTRICTED');
CREATE TYPE approval_decision AS ENUM ('APPROVE','REQUEST_CHANGES','REJECT');
CREATE TABLE departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, parent_id uuid REFERENCES departments(id), odoo_external_id text UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_code text UNIQUE NOT NULL, username citext UNIQUE, full_name text NOT NULL, email citext UNIQUE, password_hash text NOT NULL, department_id uuid REFERENCES departments(id), is_active boolean NOT NULL DEFAULT true, must_change_password boolean NOT NULL DEFAULT true, token_version integer NOT NULL DEFAULT 1, odoo_external_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL);
CREATE TABLE role_permissions (role_id uuid NOT NULL REFERENCES roles(id), permission_id uuid NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL REFERENCES roles(id), scope_department_id uuid REFERENCES departments(id), UNIQUE(user_id,role_id,scope_department_id));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), session_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE production_processes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE equipment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, process_id uuid REFERENCES production_processes(id), odoo_external_id text UNIQUE);
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid REFERENCES categories(id), name text NOT NULL, slug text UNIQUE NOT NULL);
CREATE TABLE tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL, slug text UNIQUE NOT NULL);
CREATE TABLE contents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, kind text NOT NULL CHECK(kind IN ('DOCUMENT','ARTICLE','INCIDENT_GUIDE')), title text NOT NULL, owner_department_id uuid REFERENCES departments(id), creator_id uuid NOT NULL REFERENCES users(id), visibility visibility_level NOT NULL DEFAULT 'DEPARTMENT', category_id uuid REFERENCES categories(id), current_published_version_id uuid, created_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz);
CREATE TABLE content_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_id uuid NOT NULL REFERENCES contents(id), version_number integer NOT NULL CHECK(version_number>0), body jsonb NOT NULL, status content_state NOT NULL DEFAULT 'DRAFT', created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), effective_at timestamptz, approved_at timestamptz, approved_by uuid REFERENCES users(id), UNIQUE(content_id,version_number));
ALTER TABLE contents ADD CONSTRAINT fk_current_version FOREIGN KEY(current_published_version_id) REFERENCES content_versions(id);
CREATE TABLE content_processes(content_id uuid REFERENCES contents(id), process_id uuid REFERENCES production_processes(id), PRIMARY KEY(content_id,process_id));
CREATE TABLE content_tags(content_id uuid REFERENCES contents(id), tag_id uuid REFERENCES tags(id), PRIMARY KEY(content_id,tag_id));
CREATE TABLE content_acl(content_id uuid REFERENCES contents(id), department_id uuid REFERENCES departments(id), PRIMARY KEY(content_id,department_id));
CREATE TABLE attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_version_id uuid REFERENCES content_versions(id), filename text NOT NULL, storage_key text UNIQUE NOT NULL, mime_type text NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>=0), sha256 text NOT NULL, malware_scan_status text NOT NULL DEFAULT 'PENDING', uploaded_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL UNIQUE REFERENCES content_versions(id), assigned_department_id uuid NOT NULL REFERENCES departments(id), assigned_user_id uuid REFERENCES users(id), status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','CHANGES_REQUESTED','REJECTED')), requested_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, decided_by uuid REFERENCES users(id), remark text);
CREATE TABLE approval_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), approval_id uuid NOT NULL REFERENCES approvals(id), actor_id uuid NOT NULL REFERENCES users(id), decision approval_decision NOT NULL, remark text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reading_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), version_id uuid NOT NULL REFERENCES content_versions(id), due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,version_id));
CREATE TABLE reading_acks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid UNIQUE NOT NULL REFERENCES reading_assignments(id), acknowledged_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, title text NOT NULL, process_id uuid REFERENCES production_processes(id), equipment_id uuid REFERENCES equipment(id), reporter_id uuid NOT NULL REFERENCES users(id), severity text NOT NULL CHECK(severity IN ('LOW','MEDIUM','HIGH','CRITICAL')), symptoms text NOT NULL, conditions jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incident_solutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id), proposed_by uuid NOT NULL REFERENCES users(id), cause_hypothesis text, verified_cause text, steps jsonb NOT NULL DEFAULT '[]'::jsonb, outcome text, status text NOT NULL DEFAULT 'PROPOSED' CHECK(status IN ('PROPOSED','VERIFIED','REJECTED')), verified_by uuid REFERENCES users(id), verified_at timestamptz, approved_content_version_id uuid REFERENCES content_versions(id));
CREATE TABLE incident_occurrences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id), reported_by uuid NOT NULL REFERENCES users(id), occurred_at timestamptz NOT NULL DEFAULT now(), note text, outcome text);
CREATE TABLE questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL REFERENCES users(id), department_id uuid REFERENCES departments(id), title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','DISCUSSING','RESOLVED','REOPENED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE answers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES questions(id), author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE courses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, title text NOT NULL, owner_department_id uuid REFERENCES departments(id), created_by uuid REFERENCES users(id));
CREATE TABLE course_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES courses(id), version_number integer NOT NULL, status content_state NOT NULL DEFAULT 'DRAFT', pass_score numeric(5,2) CHECK(pass_score BETWEEN 0 AND 100), max_attempts integer NOT NULL DEFAULT 3, UNIQUE(course_id,version_number));
CREATE TABLE lessons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_version_id uuid NOT NULL REFERENCES course_versions(id), title text NOT NULL, body jsonb NOT NULL, order_no integer NOT NULL, UNIQUE(course_version_id,order_no));
CREATE TABLE quiz_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_version_id uuid NOT NULL REFERENCES course_versions(id), question text NOT NULL, order_no integer NOT NULL);
CREATE TABLE quiz_options(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES quiz_questions(id), answer_text text NOT NULL, is_correct boolean NOT NULL DEFAULT false);
CREATE TABLE course_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_version_id uuid NOT NULL REFERENCES course_versions(id), user_id uuid NOT NULL REFERENCES users(id), due_at timestamptz, assigned_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(course_version_id,user_id));
CREATE TABLE lesson_progress(assignment_id uuid NOT NULL REFERENCES course_assignments(id), lesson_id uuid NOT NULL REFERENCES lessons(id), completed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(assignment_id,lesson_id));
CREATE TABLE quiz_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL REFERENCES course_assignments(id), attempt_no integer NOT NULL, score numeric(5,2), submitted_at timestamptz, UNIQUE(assignment_id,attempt_no));
CREATE TABLE quiz_responses(attempt_id uuid NOT NULL REFERENCES quiz_attempts(id), question_id uuid NOT NULL REFERENCES quiz_questions(id), option_id uuid NOT NULL REFERENCES quiz_options(id), PRIMARY KEY(attempt_id,question_id));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, old_data jsonb, new_data jsonb, request_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integration_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), connector text NOT NULL, entity_type text NOT NULL, status text NOT NULL DEFAULT 'PENDING', cursor_state jsonb, attempts integer NOT NULL DEFAULT 0, error_message text, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE INDEX idx_contents_owner ON contents(owner_department_id,kind);
CREATE INDEX idx_versions_content ON content_versions(content_id,status,version_number DESC);
CREATE INDEX idx_contents_title_trgm ON contents USING gin(title gin_trgm_ops);
CREATE INDEX idx_incident_process ON incidents(process_id,equipment_id,created_at DESC);
CREATE INDEX idx_audit_entity ON audit_logs(entity_type,entity_id,created_at DESC);
CREATE INDEX idx_notifications_user ON notifications(user_id,read_at,created_at DESC);
